import React, { useState } from "react";
import {
  Home,
  Building,
  FolderOpen,
  Mail,
  BarChart3,
  Settings,
  Plus,
  Search,
  ChevronDown,
  Edit,
  Eye,
  Trash2,
  User,
  Menu,
  X,
} from "lucide-react";

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Données de test
  const entreprises = [
    {
      id: 1,
      nom: "TechCorp SARL",
      domaines: ["Informatique", "Télécommunications"],
      canal: "Email + SMS",
      alertes: 5,
    },
    {
      id: 2,
      nom: "BatiPro SA",
      domaines: ["BTP", "Travaux publics"],
      canal: "Email",
      alertes: 2,
    },
  ];

  const alertes = [
    {
      id: 1,
      type: "Nouvelle publication",
      entreprise: "TechCorp SARL",
      titre: "Appel d'offres - Développement système informatique",
      date: "2025-06-15",
      source: "ARMP",
    },
    {
      id: 2,
      type: "Résultat de marché",
      entreprise: "BatiPro SA",
      titre: "Attribution marché construction route",
      date: "2025-06-14",
      source: "DGMP",
    },
  ];

  const menuItems = [
    { id: "accueil", label: "Accueil", icon: Home },
    { id: "entreprises", label: "Mes Entreprises", icon: Building },
    { id: "domaines", label: "Domaines d'intervention", icon: FolderOpen },
    { id: "publications", label: "Publications & Alertes", icon: Mail },
    { id: "statistiques", label: "Statistiques", icon: BarChart3 },
    { id: "parametres", label: "Paramètres", icon: Settings },
  ];

  const StatCard = ({ title, value, subtitle, gradient = false }) => (
    <div className="col-xl-3 col-lg-4 col-md-6 col-sm-12 mb-4">
      <div
        className={`card h-100 ${gradient ? "text-white" : ""}`}
        style={{
          background: gradient
            ? "linear-gradient(135deg, #003865 0%, #ef5b0c 100%)"
            : "",
          border: gradient ? "none" : "1px solid #d9d9d9",
        }}
      >
        <div className="card-body">
          <h6
            className={`card-subtitle mb-2 ${
              gradient ? "text-white-50" : "text-muted"
            }`}
          >
            {title}
          </h6>
          <h2
            className={`card-title mb-1 ${
              gradient ? "text-white" : "text-primary"
            }`}
            style={{ fontSize: "2rem", fontWeight: "bold" }}
          >
            {value}
          </h2>
          {subtitle && (
            <small className={gradient ? "text-white-50" : "text-muted"}>
              {subtitle}
            </small>
          )}
        </div>
      </div>
    </div>
  );

  const AccueilSection = () => (
    <div className="container-fluid">
      <div className="row mb-4">
        <div className="col-12">
          <div className="d-flex justify-content-between align-items-center flex-wrap">
            <h1
              className="text-primary mb-0"
              style={{ fontSize: "2rem", fontWeight: "bold" }}
            >
              Tableau de bord
            </h1>
            <div className="d-flex align-items-center">
              <div
                className="bg-success rounded-circle me-2"
                style={{
                  width: "12px",
                  height: "12px",
                  animation: "pulse 2s infinite",
                }}
              ></div>
              <small className="text-muted">En ligne</small>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        <StatCard
          title="Entreprises gérées"
          value={entreprises.length}
          subtitle="Actives"
        />
        <StatCard
          title="Alertes non lues"
          value="7"
          subtitle="Dernières 24h"
          gradient={true}
        />
        <StatCard
          title="Publications analysées"
          value="142"
          subtitle="Ce mois"
        />
        <StatCard
          title="Taux de pertinence"
          value="78%"
          subtitle="Publications filtrées"
        />
      </div>

      <div className="row">
        <div className="col-lg-6 mb-4">
          <div className="card h-100">
            <div className="card-header d-flex justify-content-between align-items-center">
              <h5 className="card-title mb-0 text-primary">Alertes récentes</h5>
              <button
                className="btn btn-link text-warning p-0"
                style={{ textDecoration: "none" }}
              >
                Voir tout
              </button>
            </div>
            <div className="card-body">
              {alertes.slice(0, 3).map((alerte) => (
                <div
                  key={alerte.id}
                  className="d-flex align-items-start mb-3 p-2 bg-light rounded"
                >
                  <div
                    className="bg-warning rounded-circle me-3 mt-2"
                    style={{ width: "8px", height: "8px" }}
                  ></div>
                  <div className="flex-grow-1">
                    <h6 className="mb-1 text-primary">{alerte.titre}</h6>
                    <small className="text-muted">
                      {alerte.entreprise} • {alerte.date}
                    </small>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="col-lg-6 mb-4">
          <div className="card h-100">
            <div className="card-header">
              <h5 className="card-title mb-0 text-primary">Raccourcis</h5>
            </div>
            <div className="card-body">
              <div className="row g-2">
                <div className="col-6">
                  <button
                    onClick={() => setActiveSection("entreprises")}
                    className="btn btn-outline-primary w-100 d-flex align-items-center justify-content-center"
                    style={{ minHeight: "50px" }}
                  >
                    <Plus size={16} className="me-2 text-warning" />
                    <span className="small">Nouvelle entreprise</span>
                  </button>
                </div>
                <div className="col-6">
                  <button
                    onClick={() => setActiveSection("publications")}
                    className="btn btn-outline-primary w-100 d-flex align-items-center justify-content-center"
                    style={{ minHeight: "50px" }}
                  >
                    <Mail size={16} className="me-2 text-warning" />
                    <span className="small">Voir alertes</span>
                  </button>
                </div>
                <div className="col-6">
                  <button
                    onClick={() => setActiveSection("domaines")}
                    className="btn btn-outline-primary w-100 d-flex align-items-center justify-content-center"
                    style={{ minHeight: "50px" }}
                  >
                    <FolderOpen size={16} className="me-2 text-warning" />
                    <span className="small">Gérer domaines</span>
                  </button>
                </div>
                <div className="col-6">
                  <button
                    onClick={() => setActiveSection("statistiques")}
                    className="btn btn-outline-primary w-100 d-flex align-items-center justify-content-center"
                    style={{ minHeight: "50px" }}
                  >
                    <BarChart3 size={16} className="me-2 text-warning" />
                    <span className="small">Statistiques</span>
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const EntreprisesSection = () => (
    <div className="container-fluid">
      <div className="row mb-4">
        <div className="col-12">
          <div className="d-flex justify-content-between align-items-center flex-wrap">
            <h1
              className="text-primary mb-0"
              style={{ fontSize: "2rem", fontWeight: "bold" }}
            >
              Mes Entreprises
            </h1>
            <button className="btn btn-warning d-flex align-items-center">
              <Plus size={16} className="me-2" />
              <span>Ajouter une entreprise</span>
            </button>
          </div>
        </div>
      </div>

      <div className="row">
        {entreprises.map((entreprise) => (
          <div key={entreprise.id} className="col-lg-6 col-xl-4 mb-4">
            <div className="card h-100">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-start mb-3">
                  <div>
                    <h5 className="card-title text-primary mb-1">
                      {entreprise.nom}
                    </h5>
                    <p className="card-text text-muted small mb-0">
                      {entreprise.domaines.join(", ")}
                    </p>
                  </div>
                  {entreprise.alertes > 0 && (
                    <span className="badge bg-warning text-dark">
                      {entreprise.alertes} alertes
                    </span>
                  )}
                </div>

                <div className="mb-3">
                  <small className="text-muted">Canal de notification :</small>
                  <p className="mb-0 fw-bold text-primary">
                    {entreprise.canal}
                  </p>
                </div>

                <div className="d-flex gap-2">
                  <button className="btn btn-outline-primary btn-sm flex-fill">
                    <Edit size={14} className="me-1" />
                    Modifier
                  </button>
                  <button className="btn btn-outline-warning btn-sm flex-fill">
                    <Eye size={14} className="me-1" />
                    Alertes
                  </button>
                  <button className="btn btn-outline-danger btn-sm">
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const PublicationsSection = () => (
    <div className="container-fluid">
      <div className="row mb-4">
        <div className="col-12">
          <div className="d-flex justify-content-between align-items-center flex-wrap">
            <h1
              className="text-primary mb-0"
              style={{ fontSize: "2rem", fontWeight: "bold" }}
            >
              Publications & Alertes
            </h1>
            <div className="d-flex align-items-center gap-2">
              <div className="input-group" style={{ maxWidth: "300px" }}>
                <span className="input-group-text">
                  <Search size={16} />
                </span>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Rechercher..."
                />
              </div>
              <button className="btn btn-outline-secondary">
                <ChevronDown size={16} />
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-12">
          <div className="card">
            <div className="card-header">
              <h5 className="card-title mb-0 text-primary">Alertes récentes</h5>
            </div>
            <div className="card-body p-0">
              {alertes.map((alerte, index) => (
                <div
                  key={alerte.id}
                  className={`p-3 ${
                    index < alertes.length - 1 ? "border-bottom" : ""
                  }`}
                  style={{ transition: "background-color 0.2s" }}
                  onMouseEnter={(e) =>
                    (e.currentTarget.style.backgroundColor = "#f8f9fa")
                  }
                  onMouseLeave={(e) =>
                    (e.currentTarget.style.backgroundColor = "transparent")
                  }
                >
                  <div className="d-flex justify-content-between align-items-start flex-wrap">
                    <div className="flex-grow-1 me-3">
                      <div className="d-flex align-items-center flex-wrap mb-2">
                        <span className="badge bg-primary me-2 mb-1">
                          {alerte.type}
                        </span>
                        <small className="text-muted mb-1">
                          {alerte.entreprise}
                        </small>
                      </div>
                      <h6 className="text-primary mb-1">{alerte.titre}</h6>
                      <small className="text-muted">
                        {alerte.source} • {alerte.date}
                      </small>
                    </div>
                    <div className="d-flex gap-2 mt-2 mt-md-0">
                      <button className="btn btn-outline-primary btn-sm">
                        Voir PDF
                      </button>
                      <button className="btn btn-outline-warning btn-sm">
                        Détails
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSection = () => {
    switch (activeSection) {
      case "accueil":
        return <AccueilSection />;
      case "entreprises":
        return <EntreprisesSection />;
      case "domaines":
        return (
          <div className="container-fluid">
            <div className="row justify-content-center">
              <div className="col-md-6 text-center">
                <FolderOpen size={64} className="text-primary mb-3" />
                <h2 className="text-primary mb-3">Domaines d'intervention</h2>
                <p className="text-muted">
                  Cette section sera développée prochainement
                </p>
              </div>
            </div>
          </div>
        );
      case "publications":
        return <PublicationsSection />;
      case "statistiques":
        return (
          <div className="container-fluid">
            <div className="row justify-content-center">
              <div className="col-md-6 text-center">
                <BarChart3 size={64} className="text-primary mb-3" />
                <h2 className="text-primary mb-3">Statistiques</h2>
                <p className="text-muted">
                  Tableau de bord analytique en cours de développement
                </p>
              </div>
            </div>
          </div>
        );
      case "parametres":
        return (
          <div className="container-fluid">
            <div className="row justify-content-center">
              <div className="col-md-6 text-center">
                <Settings size={64} className="text-primary mb-3" />
                <h2 className="text-primary mb-3">Paramètres utilisateur</h2>
                <p className="text-muted">
                  Gestion des préférences utilisateur
                </p>
              </div>
            </div>
          </div>
        );
      default:
        return <AccueilSection />;
    }
  };

  return (
    <>
      <link
        href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/css/bootstrap.min.css"
        rel="stylesheet"
      />
      <style jsx>{`
        @keyframes pulse {
          0%,
          100% {
            opacity: 1;
          }
          50% {
            opacity: 0.5;
          }
        }
        :root {
          --bs-primary: #003865;
          --bs-warning: #ef5b0c;
        }
        .sidebar {
          background-color: #003865;
          color: white;
          transition: all 0.3s ease;
          position: fixed;
          top: 0;
          left: 0;
          height: 100vh;
          z-index: 1000;
        }
        .sidebar.collapsed {
          width: 80px;
        }
        .sidebar.expanded {
          width: 256px;
        }
        .main-content {
          transition: margin-left 0.3s ease;
          min-height: 100vh;
          background-color: #f5f5f5;
        }
        .main-content.sidebar-expanded {
          margin-left: 256px;
        }
        .main-content.sidebar-collapsed {
          margin-left: 80px;
        }
        @media (max-width: 768px) {
          .sidebar {
            transform: translateX(-100%);
          }
          .sidebar.mobile-open {
            transform: translateX(0);
          }
          .main-content {
            margin-left: 0 !important;
          }
          .mobile-menu-btn {
            position: fixed;
            top: 1rem;
            left: 1rem;
            z-index: 1001;
            background-color: #003865;
            border: none;
            color: white;
            padding: 0.5rem;
            border-radius: 0.375rem;
          }
        }
      `}</style>

      <div className="d-flex">
        {/* Mobile Menu Button */}
        <button
          className="mobile-menu-btn d-md-none"
          onClick={() => setSidebarOpen(!sidebarOpen)}
        >
          {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
        </button>

        {/* Sidebar */}
        <div
          className={`sidebar d-flex flex-column ${
            sidebarOpen ? "expanded mobile-open" : "collapsed"
          }`}
        >
          <div className="p-3 border-bottom border-secondary">
            <div className="d-flex align-items-center justify-content-between">
              <h4 className={`mb-0 text-white ${!sidebarOpen ? "d-none" : ""}`}>
                Dashboard
              </h4>
              <button
                onClick={() => setSidebarOpen(!sidebarOpen)}
                className="btn btn-link text-white p-1 d-none d-md-block"
              >
                {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
              </button>
            </div>
          </div>

          <nav className="flex-grow-1 p-3">
            <ul className="list-unstyled">
              {menuItems.map((item) => {
                const IconComponent = item.icon;
                return (
                  <li key={item.id} className="mb-2">
                    <button
                      onClick={() => {
                        setActiveSection(item.id);
                        if (window.innerWidth < 768) setSidebarOpen(false);
                      }}
                      className={`btn w-100 d-flex align-items-center text-start ${
                        activeSection === item.id
                          ? "btn-warning"
                          : "btn-link text-white-50"
                      }`}
                      style={{ textDecoration: "none" }}
                    >
                      <IconComponent size={20} className="me-3" />
                      <span className={!sidebarOpen ? "d-none" : ""}>
                        {item.label}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </nav>

          <div className="p-3 border-top border-secondary">
            <div
              className={`d-flex align-items-center ${
                !sidebarOpen ? "d-none" : ""
              }`}
            >
              <div
                className="bg-warning rounded-circle me-3 d-flex align-items-center justify-content-center"
                style={{ width: "32px", height: "32px" }}
              >
                <User size={16} className="text-dark" />
              </div>
              <div>
                <div className="fw-bold">Utilisateur</div>
                <small className="text-white-50">En ligne</small>
              </div>
            </div>
          </div>
        </div>

        {/* Mobile Overlay */}
        {sidebarOpen && (
          <div
            className="position-fixed w-100 h-100 bg-dark bg-opacity-50 d-md-none"
            style={{ zIndex: 999 }}
            onClick={() => setSidebarOpen(false)}
          />
        )}

        {/* Main Content */}
        <main
          className={`main-content p-4 w-100 ${
            sidebarOpen ? "sidebar-expanded" : "sidebar-collapsed"
          }`}
        >
          {renderSection()}
        </main>
      </div>
    </>
  );
};

export default Dashboard;
